// frontend/src/admin/components/VisitorStats.jsx
// ============================================================
//  کامپوننت نمایش آمار بازدیدکنندگان در داشبورد ادمین
//  این فایل را در پوشه frontend/src/admin/components/ کپی کن
// ============================================================

import { useState, useEffect } from 'react';
import axios from '../axiosConfig';

// ============================================================
//  کارت آمار کوچک
// ============================================================
function StatCard({ title, value, subtitle, color, icon }) {
  const borderColors = {
    green: 'border-green-500',
    blue: 'border-blue-500',
    purple: 'border-purple-500',
    amber: 'border-amber-500',
  };

  return (
    <div className={`bg-white p-4 rounded-xl shadow border-r-4 ${borderColors[color] || borderColors.blue}`}>
      <div className="flex justify-between items-start">
        <div>
          <p className="text-gray-500 text-sm">{title}</p>
          <p className="text-2xl font-bold mt-1">{value.toLocaleString('fa-IR')}</p>
          {subtitle && <p className="text-xs text-gray-400 mt-1">{subtitle}</p>}
        </div>
        <span className="text-2xl">{icon}</span>
      </div>
    </div>
  );
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function VisitorStats() {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const fetchStats = () => {
    axios
      .get('/admin/dashboard/visitors')
      .then((res) => {
        setStats(res.data);
        setLoading(false);
        setError('');
      })
      .catch((err) => {
        setError('خطا در دریافت آمار بازدید');
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchStats();
    // هر ۳۰ ثانیه آپدیت
    const interval = setInterval(fetchStats, 30000);
    return () => clearInterval(interval);
  }, []);

  // ===== حالت در حال بارگذاری =====
  if (loading) {
    return (
      <div className="bg-white p-6 rounded-xl shadow mb-6">
        <div className="animate-pulse">
          <div className="h-6 bg-gray-200 rounded w-1/4 mb-4"></div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {[1, 2, 3, 4].map((i) => (
              <div key={i} className="h-24 bg-gray-200 rounded"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // ===== حالت خطا =====
  if (error) {
    return (
      <div className="bg-red-50 p-4 rounded-xl mb-6 text-red-600 text-sm">
        {error}
      </div>
    );
  }

  if (!stats) return null;

  // محاسبه بیشترین بازدید برای نمودار
  const maxDaily = Math.max(...stats.daily_series.map((d) => d.total), 1);

  return (
    <div className="mb-6">
      <h2 className="text-xl font-bold mb-4">آمار بازدیدکنندگان</h2>

      {/* ===== کارت‌های آمار ===== */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        <StatCard
          title="آنلاین هم‌اکنون"
          value={stats.online_now.total}
          subtitle={`${stats.online_now.users} کاربر / ${stats.online_now.guests} مهمان`}
          color="green"
          icon="🟢"
        />
        <StatCard
          title="بازدید امروز"
          value={stats.today.total}
          subtitle={`${stats.today.users} کاربر / ${stats.today.guests} مهمان`}
          color="blue"
          icon="📅"
        />
        <StatCard
          title="بازدید این هفته"
          value={stats.week.total}
          color="purple"
          icon="📊"
        />
        <StatCard
          title="بازدید این ماه"
          value={stats.month.total}
          color="amber"
          icon="🗓️"
        />
      </div>

      {/* ===== نمودار ۷ روز اخیر ===== */}
      <div className="bg-white p-6 rounded-xl shadow mb-6">
        <h3 className="font-bold mb-4">نمودار بازدید ۷ روز اخیر</h3>
        <div className="flex items-end gap-2 h-40">
          {stats.daily_series.map((day, i) => (
            <div key={i} className="flex-1 flex flex-col items-center">
              <div className="w-full flex flex-col-reverse gap-0.5 h-32 justify-start">
                {/* ستون کاربران */}
                <div
                  className="bg-blue-500 rounded-t transition-all"
                  style={{
                    height: `${(day.users / maxDaily) * 100}%`,
                    minHeight: day.users > 0 ? '4px' : '0',
                  }}
                  title={`کاربر: ${day.users}`}
                />
                {/* ستون مهمان‌ها */}
                <div
                  className="bg-gray-300 transition-all"
                  style={{
                    height: `${(day.guests / maxDaily) * 100}%`,
                    minHeight: day.guests > 0 ? '4px' : '0',
                  }}
                  title={`مهمان: ${day.guests}`}
                />
              </div>
              <span className="text-xs mt-2 text-gray-500">{day.date.slice(5)}</span>
              <span className="text-xs font-bold">{day.total.toLocaleString('fa-IR')}</span>
            </div>
          ))}
        </div>
        {/* راهنمای نمودار */}
        <div className="flex gap-4 mt-4 text-sm">
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 bg-blue-500 rounded"></div>
            <span>کاربران لاگین‌کرده</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 bg-gray-300 rounded"></div>
            <span>مهمان‌ها</span>
          </div>
        </div>
      </div>

      {/* ===== آخرین بازدیدها + تفکیک دستگاه ===== */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* آخرین بازدیدکنندگان */}
        <div className="md:col-span-2 bg-white p-6 rounded-xl shadow">
          <h3 className="font-bold mb-4">آخرین بازدیدکنندگان</h3>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-right border-b text-gray-500">
                  <th className="py-2">نوع</th>
                  <th>دستگاه</th>
                  <th>صفحه</th>
                  <th>آخرین فعالیت</th>
                  <th>وضعیت</th>
                </tr>
              </thead>
              <tbody>
                {stats.recent_visitors.map((v, i) => (
                  <tr key={i} className="border-b hover:bg-gray-50">
                    <td className="py-2">{v.user_id ? '👤 کاربر' : '👻 مهمان'}</td>
                    <td>
                      {v.device === 'mobile' ? '📱' : v.device === 'tablet' ? '📲' : '💻'}{' '}
                      {v.device}
                    </td>
                    <td>{v.page_views.toLocaleString('fa-IR')}</td>
                    <td>
                      {v.last_activity
                        ? new Date(v.last_activity).toLocaleTimeString('fa-IR')
                        : '—'}
                    </td>
                    <td>
                      {v.is_online ? (
                        <span className="text-green-600">🟢 آنلاین</span>
                      ) : (
                        <span className="text-gray-400">⚪ آفلاین</span>
                      )}
                    </td>
                  </tr>
                ))}
                {stats.recent_visitors.length === 0 && (
                  <tr>
                    <td colSpan="5" className="text-center text-gray-400 py-4">
                      هنوز بازدیدی ثبت نشده است
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* تفکیک دستگاه + کل بازدید */}
        <div className="bg-white p-6 rounded-xl shadow">
          <h3 className="font-bold mb-4">تفکیک دستگاه (امروز)</h3>
          <div className="space-y-3">
            {stats.device_breakdown.map((d, i) => {
              const total = stats.today.total || 1;
              const pct = ((d.count / total) * 100).toFixed(0);
              return (
                <div key={i}>
                  <div className="flex justify-between mb-1">
                    <span className="text-sm">
                      {d.device === 'mobile'
                        ? '📱 موبایل'
                        : d.device === 'tablet'
                        ? '📲 تبلت'
                        : '💻 دسکتاپ'}
                    </span>
                    <span className="text-sm font-bold">
                      {d.count.toLocaleString('fa-IR')} ({pct}٪)
                    </span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-2">
                    <div
                      className="bg-blue-500 h-2 rounded-full transition-all"
                      style={{ width: `${pct}%` }}
                    />
                  </div>
                </div>
              );
            })}
            {stats.device_breakdown.length === 0 && (
              <p className="text-gray-400 text-sm">هنوز بازدیدی ثبت نشده است</p>
            )}
          </div>

          {/* کل بازدیدها */}
          <div className="mt-6 pt-4 border-t">
            <p className="text-sm text-gray-500">کل بازدیدها (کلی)</p>
            <p className="text-2xl font-bold">
              {stats.all_time.total.toLocaleString('fa-IR')}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
